// Generated by vibes-espmatter – which endpoints (lights, plugs, sensors) each user (not admin)
// sees, and which of them they may also control (the others they only view).
//
// Kept in NVS per user name; an admin picks them on the admin dashboard ("Dashboard access"). This is
// the access rule of the Matter controller's API (mesp_matter_set_access), which the user
// dashboard's tiles and features like timers go through. Admins see everything anyway.
#include "espm_config.h"
#include "espm_matter_web.h"

#include <cstring>
#include <esp_log.h>
#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>
#include <nvs.h>
#include <string>

static const char *TAG = "mesp_access";

#define MAX_ENTRIES 10
#define MAX_ENDPOINTS 16
#define ENDPOINT_VIEW_ONLY 0x1

// Layout is stored in NVS as is – only append, never reorder.
struct entry_t {
    char user[24];
    uint8_t count;
    uint8_t reserved[7];
    struct {
        uint64_t node;
        uint16_t ep;
        uint16_t flags; // ENDPOINT_VIEW_ONLY; 0 (control) in entries from before there were flags
        uint16_t reserved[2];
    } endpoints[MAX_ENDPOINTS];
};

static entry_t s_entries[MAX_ENTRIES];
static size_t s_count = 0;
static SemaphoreHandle_t s_mutex;

namespace {
struct Lock {
    Lock() { xSemaphoreTakeRecursive(s_mutex, portMAX_DELAY); }
    ~Lock() { xSemaphoreGiveRecursive(s_mutex); }
};
} // namespace

// The NVS namespace is from when this was part of the dashboard: kept, so users keep their endpoints.
static void save()
{
    nvs_handle_t h;
    if (nvs_open("mesp_dash", NVS_READWRITE, &h) != ESP_OK) return;
    nvs_set_blob(h, "access", s_entries, s_count * sizeof(entry_t));
    nvs_commit(h);
    nvs_close(h);
}

static int find(const char *user)
{
    for (size_t i = 0; i < s_count; i++)
        if (strcmp(s_entries[i].user, user) == 0) return i;
    return -1;
}

static mesp_access_t user_access(const char *user, uint64_t node, uint16_t ep)
{
    Lock lock;
    int idx = find(user);
    if (idx < 0) return MESP_ACCESS_NONE;
    const entry_t &e = s_entries[idx];
    for (uint8_t i = 0; i < e.count; i++) {
        if (e.endpoints[i].node == node && e.endpoints[i].ep == ep) {
            return e.endpoints[i].flags & ENDPOINT_VIEW_ONLY ? MESP_ACCESS_VIEW : MESP_ACCESS_CONTROL;
        }
    }
    return MESP_ACCESS_NONE;
}

/** A deleted user's endpoints go with them: a new user of that name starts without any. */
static void forget(const char *user)
{
    Lock lock;
    int idx = find(user);
    if (idx < 0) return;
    for (size_t i = idx; i + 1 < s_count; i++) s_entries[i] = s_entries[i + 1];
    s_count--;
    save();
}

/** "266:1,261:1" → more endpoints of an entry, with `flags`. */
static bool parse_endpoints(const std::string &list, uint16_t flags, entry_t &e)
{
    size_t pos = 0;
    while (pos < list.size()) {
        size_t end = list.find(',', pos);
        if (end == std::string::npos) end = list.size();
        std::string item = list.substr(pos, end - pos);
        size_t colon = item.find(':');
        if (colon == std::string::npos || e.count >= MAX_ENDPOINTS) return false;
        char *e1 = nullptr, *e2 = nullptr;
        uint64_t node = strtoull(item.substr(0, colon).c_str(), &e1, 0);
        unsigned long ep = strtoul(item.substr(colon + 1).c_str(), &e2, 0);
        if (!e1 || *e1 || !e2 || *e2 || ep > 0xfffe) return false;
        for (uint8_t i = 0; i < e.count; i++)
            if (e.endpoints[i].node == node && e.endpoints[i].ep == ep) return false;
        e.endpoints[e.count].node = node;
        e.endpoints[e.count].ep = ep;
        e.endpoints[e.count].flags = flags;
        e.count++;
        pos = end + 1;
    }
    return true;
}

/** `{"users": {"<name>": [{"node", "endpoint", "readOnly"?}]}}` – users without endpoints are left out. */
static esp_err_t access_get(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    Json j;
    {
        Lock lock;
        j.obj().key("max").num(MAX_ENDPOINTS).key("users").obj();
        for (size_t i = 0; i < s_count; i++) {
            const entry_t &e = s_entries[i];
            j.key(e.user).arr();
            for (uint8_t l = 0; l < e.count; l++) {
                j.obj().key("node").unum(e.endpoints[l].node).key("endpoint").num(e.endpoints[l].ep);
                if (e.endpoints[l].flags & ENDPOINT_VIEW_ONLY) j.key("readOnly").boolean(true);
                j.end_obj();
            }
            j.end_arr();
        }
        j.end_obj().end_obj();
    }
    return mesp_web_send_json(req, j.out());
}

/**
 * `user=<name>&control=266:1,261:1&view=270:1` sets the endpoints a user controls and those they
 * only view (empty: none). `lights` is the old name of `control`.
 */
static esp_err_t access_post(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    std::string body, user, control, view;
    if (!mesp_web_read_body(req, body)) return ESP_OK;
    mesp_web_param(body, "user", user);
    if (!mesp_web_param(body, "control", control)) mesp_web_param(body, "lights", control);
    mesp_web_param(body, "view", view);
    if (user.empty() || user.size() >= sizeof(entry_t::user)) {
        return mesp_web_send_error(req, "400 Bad Request", "invalid user name");
    }
    entry_t e = {};
    strlcpy(e.user, user.c_str(), sizeof(e.user));
    if (!parse_endpoints(control, 0, e) || !parse_endpoints(view, ENDPOINT_VIEW_ONLY, e)) return mesp_web_send_error(req, "400 Bad Request", "invalid endpoint list");

    Lock lock;
    int idx = find(e.user);
    if (e.count == 0) {
        if (idx >= 0) {
            for (size_t i = idx; i + 1 < s_count; i++) s_entries[i] = s_entries[i + 1];
            s_count--;
        }
    } else if (idx >= 0) {
        s_entries[idx] = e;
    } else if (s_count < MAX_ENTRIES) {
        s_entries[s_count++] = e;
    } else {
        return mesp_web_send_error(req, "409 Conflict", "too many users with endpoints");
    }
    save();
    return mesp_web_send_json(req, "{\"ok\":true}");
}

void mesp_matter_access_init()
{
    s_mutex = xSemaphoreCreateRecursiveMutex();
    nvs_handle_t h;
    if (nvs_open("mesp_dash", NVS_READONLY, &h) == ESP_OK) {
        size_t len = sizeof(s_entries);
        if (nvs_get_blob(h, "access", s_entries, &len) == ESP_OK) s_count = len / sizeof(entry_t);
        nvs_close(h);
    }
    ESP_LOGI(TAG, "endpoints for %u users", (unsigned)s_count);
    mesp_matter_set_access(user_access);
    mesp_web_on_user_removed(forget);
}

void mesp_matter_access_register_web()
{
    mesp_web_add("/api/matter/access", HTTP_GET, access_get);
    mesp_web_add("/api/matter/access", HTTP_POST, access_post);
}
